    static JSONObject issuedSource(String id,String source,String quantity,boolean material)throws Exception {JSONObject allocation=new JSONObject().put(source,quantity),line=new JSONObject().put("quantity",new BigDecimal(quantity)).put("unit",material?"Sack":"h");if(material)line.put("source_type","material_movement").put("source_id",source).put("source_quantity_decimal",quantity);else line.put("worklog_id",source);return new JSONObject().put("id",id).put("customer_id","qa_customer_1").put("issued_at","2027-05-18T08:00:00Z").put("status","Gestellt").put("local_issue_request","qa_issue_"+id).put("numbering_receipt",new JSONObject().put("authority",LocalAuthorityRules.ENGINE)).put("local_source_allocations",material?new JSONObject():copy(allocation)).put("local_material_source_allocations",material?copy(allocation):new JSONObject()).put("worklog_ids",material?new JSONArray():new JSONArray().put(source)).put("positions",new JSONArray().put(line));}
    static void addIssuedSource(JSONObject state,JSONObject dependencies,String id,String source,String quantity,boolean material)throws Exception {state.getJSONArray("invoices").put(issuedSource(id,source,quantity,material));dependencies.getJSONObject("worklog_allocations_by_invoice").put(id,material?new JSONObject():new JSONObject().put(source,quantity));dependencies.getJSONObject("material_allocations_by_invoice").put(id,material?new JSONObject().put(source,quantity):new JSONObject());LocalBillingRules.validate(state,new JSONObject().put("formatVersion",1).put("by_invoice",dependencies.getJSONObject("worklog_allocations_by_invoice")));}
