        JSONObject overWorkState=state(),overWorkDependencies=dependencies();String work=overWorkState.getJSONArray("worklogs").getJSONObject(0).getString("id");overWorkState.getJSONArray("invoices").put(issuedSource("qa_work_overallocated",work,"3",false));overWorkDependencies.getJSONObject("worklog_allocations_by_invoice").put("qa_work_overallocated",new JSONObject().put(work,"3"));overWorkDependencies.getJSONObject("material_allocations_by_invoice").put("qa_work_overallocated",new JSONObject());JSONObject overWork=review(overWorkState,overWorkDependencies);yes(!overWork.getBoolean("ready")&&overWork.getJSONObject("snapshot").getJSONArray("worklogs").getJSONObject(0).getJSONObject("billing_quantity").isNull("remaining_decimal"));
        JSONObject malformed=copy(dependencies);malformed.getJSONObject("material_allocations_by_invoice").getJSONObject("qa_material_allocation").put(MATERIAL,"qa_unklare_menge");JSONObject unknown=review(state,malformed);yes(!unknown.getBoolean("ready")&&unknown.getJSONObject("snapshot").getJSONArray("materials").getJSONObject(0).isNull("allocated_decimal"));
